#ifndef TF_VENDOR_MODEM_H
#define TF_VENDOR_MODEM_H
#include <sys/wait.h>
#include <sys/prctl.h>
static void vendor_reap(pid_t child,int*status){while(waitpid(child,status,0)<0&&errno==EINTR){}}
static uint32_t vendor_read_at=0;static int vendor_read_once=0;
/* No shell, no SDK initialization, bounded output and elapsed time. */
static int vendor_exec_timeout(const char*path,char*const argv[],const char*input,char*out,size_t cap,int timeout_ms){if(tf_http_cancelled||timeout_ms<1||timeout_ms>6000||cap<2)return -1;int in[2]={-1,-1},p[2]={-1,-1};out[0]=0;if(pipe(in)||pipe(p)){for(int i=0;i<2;i++){if(in[i]>=0)close(in[i]);if(p[i]>=0)close(p[i]);}return-1;}pid_t parent=getpid(),child=fork();if(child==0){if(prctl(PR_SET_PDEATHSIG,SIGKILL)<0||getppid()!=parent)_exit(127);dup2(in[0],0);dup2(p[1],1);int null=open("/dev/null",O_WRONLY);if(null>=0){dup2(null,2);close(null);}close(in[0]);close(in[1]);close(p[0]);close(p[1]);for(int fd=3;fd<256;fd++)close(fd);execv(path,argv);_exit(127);}close(in[0]);close(p[1]);if(child<0){close(in[1]);close(p[0]);return-1;}if(input&&*input){size_t length=strlen(input);if(write(in[1],input,length)!=(ssize_t)length){close(in[1]);close(p[0]);kill(child,SIGKILL);vendor_reap(child,NULL);return-1;}}close(in[1]);fcntl(p[0],F_SETFL,O_NONBLOCK);long long deadline=tf_monotonic_ms()+timeout_ms;size_t n=0;int status=0,done=0,failed=0;
 while(!tf_http_cancelled&&tf_monotonic_ms()<deadline){ssize_t got=read(p[0],out+n,cap-n-1);if(got>0){n+=(size_t)got;if(n>=cap-1){failed=1;break;}}else if(got<0&&errno!=EAGAIN&&errno!=EINTR){failed=1;break;}pid_t result=waitpid(child,&status,WNOHANG);if(result==child){done=1;while(n<cap-1&&(got=read(p[0],out+n,cap-n-1))>0)n+=(size_t)got;if(n>=cap-1)failed=1;break;}if(result<0&&errno==EINTR)continue;if(result<0){failed=1;break;}struct pollfd wait={p[0],POLLIN,0};poll(&wait,1,20);if(tf_http_wait_hook)tf_http_wait_hook();}
 if(!done){kill(child,SIGKILL);vendor_reap(child,&status);failed=1;}close(p[0]);out[n]=0;return !failed&&done&&WIFEXITED(status)?WEXITSTATUS(status):-1;
}
static int vendor_exec(const char*path,char*const argv[],const char*input,char*out,size_t cap){return vendor_exec_timeout(path,argv,input,out,cap,1800);}
static void vendor_refresh(int force){uint32_t now=tick();if(!force&&vendor_read_once&&now-vendor_read_at<10000)return;vendor_read_once=1;vendor_read_at=now;tf_external_enabled[0]=tf_external_enabled[1]=-1;char output[512];char*const args[]={"uci","-q","batch",NULL};const char*input="show zwrt_zte_mc.mc_status.V3E2_lpr_flight_status\nshow zwrt_zte_mc.mc_status.V3E1_lpr_flight_status\n";if(vendor_exec("/sbin/uci",args,input,output,sizeof output))return;const char*keys[]={"zwrt_zte_mc.mc_status.V3E2_lpr_flight_status=","zwrt_zte_mc.mc_status.V3E1_lpr_flight_status="};for(int i=0;i<2;i++){char*line=output;while(*line){char*end=strchr(line,'\n');size_t n=end?(size_t)(end-line):strlen(line),keylen=strlen(keys[i]);if(n>=keylen&&!memcmp(line,keys[i],keylen)){const char*v=line+keylen;size_t len=n-keylen;if(len&&v[len-1]=='\r')len--;if((len==5&&!memcmp(v,"'off'",5))||(len==3&&!memcmp(v,"off",3)))tf_external_enabled[i]=1;else if((len==4&&!memcmp(v,"'on'",4))||(len==2&&!memcmp(v,"on",2)))tf_external_enabled[i]=0;}if(!end)break;line=end+1;}}memset(output,0,sizeof output);}
static int vendor_set_enabled(const char*id,int enabled){if((strcmp(id,"4G1")&&strcmp(id,"4G2"))||(enabled!=0&&enabled!=1))return 0;char payload[256],response[4096];snprintf(payload,sizeof payload,"{\"moduleName\":\"zte_topsw_devui\",\"source_module\":\"zte_topsw_devui\",\"action\":\"%s\",\"parameter\":\"%s\"}",enabled?"off":"on",!strcmp(id,"4G1")?"V3E2":"V3E1");char*const args[]={"ubus","-t","1","call","zwrt_mc.device.manager","device_tsp_lpr_flight_mode_set",payload,NULL};return vendor_exec("/bin/ubus",args,NULL,response,sizeof response)==0;}
static int vendor_apn_read(int slot,const char*method,char*out,size_t cap){if(slot!=101&&slot!=201)return 0;if(strcmp(method,"get_apn_mode")&&strcmp(method,"getAutoApnList")&&strcmp(method,"getManuApnList")&&strcmp(method,"get_enabled_manu_apn_id"))return 0;char payload[32];snprintf(payload,sizeof payload,"{\"slotId\":%d}",slot);char*const args[]={"ubus","-t","1","call","zwrt_apn_object",(char*)method,payload,NULL};return vendor_exec("/bin/ubus",args,NULL,out,cap)==0;}
#endif
